function [z, src, dst] = kpi_merge(src, dst, m, wd)
%KPI_MERGE  One pass of the merge sort: the runs of width wd of src[0..m] merged in pairs into dst, ascending, a tie to the
%   earlier run.
%   length: 64
%   src: inout real[1][*] (passed a plain number)
%   dst: inout real[1][*] (passed a plain number)
%   m: int (passed a whole number)
%   wd: int (passed a whole number)
%   returns z: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    z = 0;
    z = 0;
    nb = fix((((m + (2 * wd)) - 1)) / ((2 * wd)));
    for bk = (0):((nb) - 1)
        lo = ((bk * 2) * wd);
        mid = asils.pc.fmin((lo + wd), m);
        hi = asils.pc.fmin((lo + (2 * wd)), m);
        i = lo;
        j = mid;
        for k = (lo):((hi) - 1)
            if ((i < mid) && ((j >= hi) || (~(src((j) + 1) < src((i) + 1)))))
                dst((k) + 1) = src((i) + 1);
                i = (i + 1);
            else
                dst((k) + 1) = src((j) + 1);
                j = (j + 1);
            end
        end
    end
end
